<script setup lang="ts">
import { onMounted,onUnmounted,ref,watch } from 'vue';
import type { SourceFile } from '../services/workspace';
const props=defineProps<{projectId:string;file:SourceFile|null;disabled?:boolean}>();
const entries=ref<{id:string;path:string;sha256:string;chunks:number;indexedAt:string;current:boolean}[]>([]),busy=ref(false),error=ref('');let disposed=false;
async function request(suffix='',input?:unknown){const response=await fetch(`/api/projects/${props.projectId}/memory/code${suffix}`,input===undefined?undefined:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(input)});const result=await response.json().catch(()=>null);if(!response.ok)throw new Error(result?.error?.message??'No se pudo preparar la memoria del archivo.');return result;}
async function load(){const target=props.projectId;try{const result=await request();if(!disposed&&props.projectId===target)entries.value=result.files;}catch(cause){if(!disposed)error.value=(cause as Error).message;}}
async function act(id?:string){if(!id&&!props.file)return;busy.value=true;error.value='';const target=props.projectId;try{const result=await request(id?'/remove':'',id?{id}:{path:props.file!.path,sha256:props.file!.sha256});if(!disposed&&props.projectId===target)entries.value=result.files;}catch(cause){if(!disposed)error.value=(cause as Error).message;}finally{busy.value=false;}}
watch(()=>props.projectId,()=>{entries.value=[];error.value='';void load();});onMounted(()=>{void load();});onUnmounted(()=>{disposed=true;});
</script>
<template><section class="code-memory" aria-label="Memoria del código"><div class="result-toolbar"><h3>Memoria del código seleccionado</h3><button class="connection-action" :disabled="busy||disabled" @click="load">Actualizar índice de código</button></div><p class="muted">Indexar envía únicamente el archivo leído a Gemini para calcular embeddings y guarda sus fragmentos en PostgreSQL. Se excluyen secretos y archivos que cambien después. Máximo: 50 archivos de 64 KB por proyecto.</p><button class="connection-action" :disabled="busy||disabled||!file||file.redacted" @click="act()">Indexar archivo leído con Gemini</button><p v-if="busy" role="status">Preparando memoria del archivo…</p><p v-if="error" role="alert" class="library-error">{{ error }}</p><ul><li v-for="entry in entries" :key="entry.id"><div><strong>{{ entry.path }}</strong><small>{{ entry.chunks }} fragmentos · {{ entry.current?'Vigente':'Cambió o no está disponible: vuelve a indexar' }}</small><code>{{ entry.sha256.slice(0,16) }}</code></div><button class="connection-action" :disabled="busy||disabled" @click="act(entry.id)">Retirar del índice</button></li></ul><p class="result-note">Activa Consultar memoria del proyecto en el chat para recuperar estos fragmentos junto con la documentación preparada. La segmentación es textual; no analiza el AST del lenguaje.</p></section></template>
<style scoped>.code-memory{padding:20px 0;margin-top:20px;border-top:1px solid #233a41}.code-memory ul{list-style:none;padding:0}.code-memory li{display:flex;gap:12px;justify-content:space-between;flex-wrap:wrap;margin:15px 0}.code-memory li div{display:grid;gap:8px}.code-memory strong{overflow-wrap:anywhere}.code-memory small{color:#8ba8b4;font-size:11px}</style>
